<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="referrer" content="no-referrer"><title><?= $mode==='forgot'?'Recuperar acceso':'Nueva contraseña' ?> | Tecno Star</title><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link rel="stylesheet" href="<?= app_url_html('/assets/css/accounts.css?v='.filemtime(BASE_PATH.'/public/assets/css/accounts.css')) ?>"><script defer src="<?= app_url_html('/assets/js/commerce.js?v='.filemtime(BASE_PATH.'/public/assets/js/commerce.js')) ?>"></script><script defer src="<?= app_url_html('/assets/js/accounts.js') ?>"></script></head><body class="recovery-body"><main class="recovery-card"><a href="<?= app_url_html('/store') ?>" class="recovery-brand"><img src="<?= app_url_html('/assets/images/logo-estrella.png') ?>" alt="">Tecno Star</a><span class="recovery-eyebrow">Tu cuenta</span><h1><?= $mode==='forgot'?'Recupera tu acceso':'Crea una nueva contraseña' ?></h1><p><?= $mode==='forgot'?'Te enviaremos un enlace de un solo uso al correo de tu cuenta.':'El enlace vence a los 20 minutos. Al guardar se cerrarán tus sesiones anteriores.' ?></p>
